        one[0] = 0;
        require(wrapper.rawCall(address(r), id, one), "dup ok");
        _eq(r.winningEntry(), 5 % 3 + 1, "unchanged");
    }

    function test_vrf_feeExcessRefund_and_insufficient() public {
        uint64 end = uint64(T0 + 1 days);
        Raffle r = _create(1, 5, end);
