            sponsor: alice,
            sponsorRecipient: alice,
            protocolTreasury: alice,
            prizeToken: address(nft),
            prizeTokenId: 1,
            raffleId: 1,
            reserveEntries: 1,
            endTime: uint64(T0 + 1 days)
        });
