        vm.prank(alice);
        _eq(r.refundTickets(ids), 3 * E, "full refund");
        r.releaseSponsorPrize();
        require(nft.ownerOf(1) == recipient, "prize returned");
    }

    function test_edges_emptyRaffle() public {
        uint64 end = uint64(T0 + 1 days);
        Raffle r = _create(1, 5, end);
        vm.warp(end - 1);
