            require(
                (st == IRaffle.Status.CashWon || st == IRaffle.Status.Refunding) && nft.ownerOf(prizeId) == recipient,
                "I7 sponsor return"
            );
        }
        _eq(address(r).balance, 0, "I8 native");
    }
